local script=debug.getinfo(1,'S').source:sub(2);local dir=script:match('^(.*)[/\\]');package.path=dir..'/?.lua;'..package.path
local b=require('_bootstrap');local a=b.lib('args');local o=a.parse(arg);local path=b.lib('path');local process=b.lib('process');local exe=path.absolute(a.required(o,'exe'));local cwd=path.absolute(a.required(o,'cwd'));local pidfile=path.absolute(a.required(o,'pid-file'));local team=a.integer(a.required(o,'team'),'team',1,2);local logdir=path.join(path.parent(pidfile),'runtime-logs');path.mkdir_p(logdir);local argv={'--player-id',a.required(o,'player-id'),'--team',tostring(team),'--player-name',a.required(o,'player-name'),'--server',a.required(o,'server'),'--presentation-bind',a.required(o,'presentation-addr'),'--presentation-hz','60','--protocol-version','2','--scripted-move-tick','300','--scripted-hidden-target-tick','420','--screenshot-tick','600'};local evidence=o['evidence-dir'];if evidence then local evidence_root=path.absolute(evidence);local shutdown_file=path.join(evidence_root,'team-'..team..'-runtime.shutdown');os.remove(shutdown_file);table.insert(argv,'--test-mode');table.insert(argv,'--evidence-dir');table.insert(argv,evidence_root);table.insert(argv,'--shutdown-file');table.insert(argv,shutdown_file);local fault=os.getenv('OMOBA_TEAM1_FAULT_TICK');if team==1 and fault then table.insert(argv,'--fault-tick');table.insert(argv,fault)end end;local stdout=path.join(logdir,'team-'..team..'.stdout.log');local stderr=path.join(logdir,'team-'..team..'.stderr.log');local pid=process.spawn(exe,argv,{cwd=cwd,stdout=stdout,stderr=stderr});process.poll_ready(pid,20000,function()local manifest=evidence and path.join(path.absolute(evidence),'team-'..team..'-runtime','manifest.json');return(manifest and path.exists(manifest))or(path.exists(stderr)and path.read(stderr):find('client-runtime ready',1,true))end,'Team '..team..' runtime');path.write(pidfile,tostring(pid)..'\r\n',true);print(pid)
